-- WoW Forever creatures and objects that quests need and our world lacks: quest givers and enders, kill targets, the creatures
-- and objects that drop quest items, and creatures whose drops no one could get.
-- Data from Everlake (GPL-3.0), commit 0ffaa3d, files 2026_11_18_926 to 931, which build them from EG Link (Efficient Games,
-- https://efficient.games, CC BY 4.0: creature and object details the live server sent players' games, builds 70888-70959),
-- QuestieDB (Questie team, GPL-3.0: Forever positions and players' QuestieTrace recordings) and Wowhead (drop counts).
-- Changed: only the creatures whose template comes from EG Link and only spawns from those sources are taken; checked against
-- our world and written as our own rows. Faction, speeds and attack times are borrowed from the nearest NPC of our world that
-- treats players the same way (no public source records a faction). Heights come from Everlake's map and vmap tool.
-- Not taken: creatures whose template only DatabaseForever has, and spawns from it or forever-db.
-- Everything goes in only where missing. Safe to run more than once.


-- 1. Creature templates (EG Link creature details; faction and speeds borrowed from a nearby NPC, see the note per creature).
DROP TEMPORARY TABLE IF EXISTS `forever_npc_ct_1120`;
CREATE TEMPORARY TABLE `forever_npc_ct_1120` SELECT `entry`,`KillCredit1`,`KillCredit2`,`name`,`femaleName`,`subname`,`TitleAlt`,`IconName`,`RequiredExpansion`,`VignetteID`,`faction`,`npcflag`,`speed_walk`,`speed_run`,`scale`,`Classification`,`dmgschool`,`BaseAttackTime`,`RangeAttackTime`,`BaseVariance`,`RangeVariance`,`unit_class`,`unit_flags`,`unit_flags2`,`unit_flags3`,`family`,`trainer_class`,`type`,`VehicleId`,`AIName`,`MovementType`,`ExperienceModifier`,`RacialLeader`,`movementId`,`WidgetSetID`,`WidgetSetUnitConditionID`,`RegenHealth`,`CreatureImmunitiesId`,`flags_extra`,`ScriptName`,`StringId`,`VerifiedBuild` FROM `creature_template` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_npc_ct_1120`;

--    Difficulty, models, levels and quest items, only where missing.
DROP TEMPORARY TABLE IF EXISTS `forever_npc_ctd_1120`;
CREATE TEMPORARY TABLE `forever_npc_ctd_1120` SELECT `Entry`,`DifficultyID`,`LevelScalingDeltaMin`,`LevelScalingDeltaMax`,`ContentTuningID`,`HealthScalingExpansion`,`HealthModifier`,`ManaModifier`,`ArmorModifier`,`DamageModifier`,`CreatureDifficultyID`,`TypeFlags`,`TypeFlags2`,`TypeFlags3`,`LootID`,`PickPocketLootID`,`SkinLootID`,`GoldMin`,`GoldMax`,`StaticFlags1`,`StaticFlags2`,`StaticFlags3`,`StaticFlags4`,`StaticFlags5`,`StaticFlags6`,`StaticFlags7`,`StaticFlags8`,`VerifiedBuild` FROM `creature_template_difficulty` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_npc_ctd_1120`;

DROP TEMPORARY TABLE IF EXISTS `forever_npc_ctm_1120`;
CREATE TEMPORARY TABLE `forever_npc_ctm_1120` SELECT `CreatureID`,`Idx`,`CreatureDisplayID`,`DisplayScale`,`Probability`,`VerifiedBuild` FROM `creature_template_model` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_npc_ctm_1120`;

DROP TEMPORARY TABLE IF EXISTS `forever_npc_ccl_1120`;
CREATE TEMPORARY TABLE `forever_npc_ccl_1120` SELECT `entry`,`level_min`,`level_max` FROM `creature_classic_level` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_npc_ccl_1120`;

DROP TEMPORARY TABLE IF EXISTS `forever_npc_cqi_1120`;
CREATE TEMPORARY TABLE `forever_npc_cqi_1120` SELECT `CreatureEntry`,`DifficultyID`,`Idx`,`ItemId`,`VerifiedBuild` FROM `creature_questitem` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_npc_cqi_1120`;

--    Model sizes for displays that had none (Everlake inferred them from similar models).
DROP TEMPORARY TABLE IF EXISTS `forever_npc_cmi_1120`;
CREATE TEMPORARY TABLE `forever_npc_cmi_1120` SELECT `DisplayID`,`BoundingRadius`,`CombatReach`,`DisplayID_Other_Gender`,`VerifiedBuild` FROM `creature_model_info` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_npc_cmi_1120`;

-- 2. Their drops: quest items (QuestRequired) and Wowhead-measured drops, only where missing.
DROP TEMPORARY TABLE IF EXISTS `forever_npc_clt_1120`;
CREATE TEMPORARY TABLE `forever_npc_clt_1120` SELECT `Entry`,`ItemType`,`Item`,`Chance`,`QuestRequired`,`LootMode`,`GroupId`,`MinCount`,`MaxCount`,`Comment` FROM `creature_loot_template` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_npc_clt_1120`;

-- 3. Quest-item objects (EG Link object details), only where missing.
DROP TEMPORARY TABLE IF EXISTS `forever_npc_gt_1120`;
CREATE TEMPORARY TABLE `forever_npc_gt_1120` SELECT `entry`,`type`,`displayId`,`name`,`IconName`,`castBarCaption`,`unk1`,`size`,`Data0`,`Data1`,`Data2`,`Data3`,`Data4`,`Data5`,`Data6`,`Data7`,`Data8`,`Data9`,`Data10`,`Data11`,`Data12`,`Data13`,`Data14`,`Data15`,`Data16`,`Data17`,`Data18`,`Data19`,`Data20`,`Data21`,`Data22`,`Data23`,`Data24`,`Data25`,`Data26`,`Data27`,`Data28`,`Data29`,`Data30`,`Data31`,`Data32`,`Data33`,`Data34`,`ContentTuningId`,`RequiredLevel`,`AIName`,`ScriptName`,`StringId`,`VerifiedBuild` FROM `gameobject_template` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_npc_gt_1120`;

DROP TEMPORARY TABLE IF EXISTS `forever_npc_gqi_1120`;
CREATE TEMPORARY TABLE `forever_npc_gqi_1120` SELECT `GameObjectEntry`,`Idx`,`ItemId`,`VerifiedBuild` FROM `gameobject_questitem` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_npc_gqi_1120`;

DROP TEMPORARY TABLE IF EXISTS `forever_npc_glt_1120`;
CREATE TEMPORARY TABLE `forever_npc_glt_1120` SELECT `Entry`,`ItemType`,`Item`,`Chance`,`QuestRequired`,`LootMode`,`GroupId`,`MinCount`,`MaxCount`,`Comment` FROM `gameobject_loot_template` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_npc_glt_1120`;

-- 4. Creature spawns (Questie player traces and generated points, EG Link sightings, Wowhead), heights from Everlake's map and vmap
--    tool. Only for a creature with no spawn of its own yet, and only where the guid is free.
DROP TEMPORARY TABLE IF EXISTS `forever_npc_cs_1120`;
CREATE TEMPORARY TABLE `forever_npc_cs_1120` SELECT `guid`,`id`,`map`,`zoneId`,`areaId`,`spawnDifficulties`,`phaseUseFlags`,`PhaseId`,`PhaseGroup`,`terrainSwapMap`,`modelid`,`equipment_id`,`position_x`,`position_y`,`position_z`,`orientation`,`spawntimesecs`,`wander_distance`,`currentwaypoint`,`curHealthPct`,`MovementType`,`npcflag`,`unit_flags`,`unit_flags2`,`unit_flags3`,`ScriptName`,`StringId`,`VerifiedBuild` FROM `creature` WHERE 0;
WHERE EXISTS (SELECT 1 FROM `creature_template` `t` WHERE `t`.`entry`=`s`.`id`)
  AND NOT EXISTS (SELECT 1 FROM `creature` `x` WHERE `x`.`guid`=`s`.`guid`)
  AND NOT EXISTS (SELECT 1 FROM `creature` `x` WHERE `x`.`id`=`s`.`id` AND `x`.`guid` NOT BETWEEN 920001000 AND 920006049);
DROP TEMPORARY TABLE IF EXISTS `forever_npc_cs_1120`;

-- 5. Object spawns, same rules.
DROP TEMPORARY TABLE IF EXISTS `forever_npc_gs_1120`;
CREATE TEMPORARY TABLE `forever_npc_gs_1120` SELECT `guid`,`id`,`map`,`zoneId`,`areaId`,`spawnDifficulties`,`PhaseId`,`PhaseGroup`,`position_x`,`position_y`,`position_z`,`orientation`,`rotation0`,`rotation1`,`rotation2`,`rotation3`,`spawntimesecs`,`animprogress`,`state`,`ScriptName`,`StringId`,`VerifiedBuild` FROM `gameobject` WHERE 0;
WHERE EXISTS (SELECT 1 FROM `gameobject_template` `t` WHERE `t`.`entry`=`s`.`id`)
  AND NOT EXISTS (SELECT 1 FROM `gameobject` `x` WHERE `x`.`guid`=`s`.`guid`)
  AND NOT EXISTS (SELECT 1 FROM `gameobject` `x` WHERE `x`.`id`=`s`.`id` AND `x`.`guid` NOT BETWEEN 920001000 AND 920006049);
DROP TEMPORARY TABLE IF EXISTS `forever_npc_gs_1120`;
